+    padding: 8px 16px;
+    cursor: pointer;
+    display: flex;
+    flex-wrap: wrap;
+    align-items: center;
+    gap: 4px;
+    border-radius: 4px;
+    margin: 2px 8px;
+    transition: background-color 0.15s;
+}
+
+.channel-item:hover {
+    background: #36393f;
+}
+
+.channel-item.active {
+    background: #393c43;
+    color: #fff;
+}
+
+.channel-name {
+    font-weight: 600;
+    font-size: 0.95rem;
+    flex: 1;
+}
+
+.channel-description {
+    width: 100%;
+    font-size: 0.75rem;
+    color: #72767d;
+    white-space: nowrap;
+    overflow: hidden;
+    text-overflow: ellipsis;
+}
+
+.unread-badge {
+    background: #ed4245;
+    color: #fff;
+    font-size: 0.7rem;
+    font-weight: 700;
+    padding: 2px 6px;
+    border-radius: 10px;
+    min-width: 18px;
+    text-align: center;
+}
+
+/* Main Message Area */
+.chat-main {
+    flex: 1;
+    display: flex;
+    min-width: 0;
+}
+
+.chat-main.thread-open {
+    flex: 0 0 55%;
+}
+
+.message-area {
+    flex: 1;
+    display: flex;
+    flex-direction: column;
+    background: #36393f;
+    color: #dcddde;
+}
+
+.channel-header {
+    padding: 12px 20px;
+    border-bottom: 1px solid #202225;
+    background: #36393f;
+}
+
+.channel-header h2 {
+    margin: 0;
+    font-size: 1.1rem;
+    color: #fff;
+}
+
+.channel-header p {
+    margin: 4px 0 0;
+    font-size: 0.8rem;
+    color: #8e9297;
+}
+
+.no-channel-selected {
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    flex: 1;
+    color: #72767d;
+}
+
+/* Message List */
+.message-list {
+    flex: 1;
+    overflow-y: auto;
+    padding: 16px 20px;
+}
+
+.loading-indicator {
+    text-align: center;
+    padding: 12px;
+    color: #8e9297;
+    font-size: 0.85rem;
+}
+
+/* Message Item */
+.message-item {
+    padding: 8px 12px;
+    margin-bottom: 4px;
+    border-radius: 4px;
+    position: relative;
+    transition: background-color 0.1s;
+}
+
+.message-item:hover {
+    background: #32353b;
+}
+
+.message-header {
+    display: flex;
+    align-items: baseline;
+    gap: 8px;
+    margin-bottom: 4px;
+}
+
+.message-author {
+    font-weight: 600;
+    color: #fff;
+    font-size: 0.9rem;
+}
+
+.message-time {
+    font-size: 0.75rem;
+    color: #72767d;
+}
+
+.message-content {
+    font-size: 0.9rem;
+    line-height: 1.4;
+    word-wrap: break-word;
+}
+
+/* Reactions */
+.message-reactions {
+    display: flex;
+    flex-wrap: wrap;
+    gap: 4px;
+    margin-top: 6px;
+}
+
+.reaction-badge {
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 12px;
+    padding: 2px 8px;
+    font-size: 0.8rem;
+    cursor: pointer;
+    transition: background-color 0.15s;
+}
+
+.reaction-badge:hover {
+    background: #4f545c;
+}
+
+/* Thread Link */
+.thread-link {
+    margin-top: 4px;
+    font-size: 0.8rem;
+    color: #00aff4;
+    cursor: pointer;
+    font-weight: 500;
+}
+
+.thread-link:hover {
+    text-decoration: underline;
+}
+
+/* Message Actions */
+.message-actions {
+    position: absolute;
+    top: -8px;
+    right: 8px;
+    display: flex;
+    gap: 4px;
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 4px;
+    padding: 2px;
+}
+
+.action-btn {
+    background: transparent;
+    border: none;
+    color: #b9bbbe;
+    padding: 4px 8px;
+    cursor: pointer;
+    font-size: 0.8rem;
+    border-radius: 3px;
+}
+
+.action-btn:hover {
+    background: #4f545c;
+    color: #fff;
+}
+
+/* Emoji Picker */
+.emoji-picker {
+    position: absolute;
+    top: -40px;
+    right: 8px;
+    display: flex;
+    gap: 4px;
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 6px;
+    padding: 6px 8px;
+    z-index: 10;
+}
+
+.emoji-option {
+    cursor: pointer;
+    font-size: 1.2rem;
+    padding: 2px 4px;
+    border-radius: 4px;
+    transition: background-color 0.1s;
+}
+
+.emoji-option:hover {
+    background: #4f545c;
+}
+
+/* Message Input */
+.message-input {
+    padding: 12px 20px;
+    display: flex;
+    gap: 8px;
+    align-items: flex-end;
+    border-top: 1px solid #202225;
+}
+
+.message-input textarea {
+    flex: 1;
+    background: #40444b;
+    border: none;
+    border-radius: 8px;
+    color: #dcddde;
+    padding: 10px 14px;
+    font-size: 0.9rem;
+    resize: none;
+    outline: none;
+    font-family: inherit;
+}
+
+.message-input textarea::placeholder {
+    color: #72767d;
+}
+
+.send-btn {
+    background: #5865f2;
+    color: #fff;
+    border: none;
+    border-radius: 6px;
+    padding: 10px 18px;
+    cursor: pointer;
+    font-weight: 600;
+    font-size: 0.85rem;
+    transition: background-color 0.15s;
+}
+
+.send-btn:hover:not(:disabled) {
+    background: #4752c4;
+}
+
+.send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread Panel */
+.thread-panel {
+    width: 25%;
+    min-width: 280px;
+    background: #2f3136;
+    color: #dcddde;
+    display: flex;
+    flex-direction: column;
+    border-left: 1px solid #202225;
+}
+
+.thread-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 12px 16px;
+    border-bottom: 1px solid #202225;
+}
+
+.thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #fff;
+}
+
+.close-btn {
+    background: transparent;
+    border: none;
+    color: #b9bbbe;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+.close-btn:hover {
+    background: #4f545c;
+    color: #fff;
+}
+
+.thread-root-message {
+    padding: 12px 16px;
+    border-bottom: 1px solid #202225;
+    background: #36393f;
+}
+
+.thread-root-message .message-author {
+    font-size: 0.85rem;
+}
+
+.thread-root-message .message-content {
+    margin-top: 4px;
+    font-size: 0.85rem;
+    color: #b9bbbe;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+}
+
+.thread-reply {
+    padding: 8px 0;
+    border-bottom: 1px solid #36393f;
+}
+
+.thread-reply:last-child {
+    border-bottom: none;
+}
